// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // 1. The reference contract requires _tos.length > 0; any call with empty array reverts.
        //    Both versions revert, so the difference is not observable. We restrict to non-empty arrays.
        vm.assume(_tos.length > 0);
        // 2. The reference returns true for all non-reverting calls; the mutant returns false.
        //    To guarantee non-reverting calls, we deploy a helper that always succeeds.
        //    Without it, the fuzzer would give an EOA where call succeeds, but we also need to handle
        //    possible reverts from real tokens. Since the difference is in the return value when no
        //    revert occurs, we use a helper that never reverts to exercise the return path.
        Helper helper = new Helper();
        // Use fuzzed from, _tos, v; but route the call through helper's address as caddress.
        // The helper always returns true for the low-level call, ensuring no revert inside the loop.
        bool result = c.transfer(from, address(helper), _tos, v);
        // 3. Assert that the reference always returns true. The mutant returns false and will fail.
        assertTrue(result);
    }
}

contract Helper {
    // This fallback is called for any calldata, simulating a successful external call.
    fallback() external payable returns (bytes memory) {
        return abi.encode(true);
    }
}
